#include "MainComponent.h"
namespace cymbalforge { MainComponent::MainComponent():editor(engine) { addAndMakeVisible(editor); setAudioChannels(0,2); auto devices=juce::MidiInput::getAvailableDevices(); if(!devices.isEmpty()) midi=juce::MidiInput::openDevice(devices[0].identifier,this); if(midi) midi->start(); setSize(1000,720); } MainComponent::~MainComponent(){ if(midi)midi->stop(); shutdownAudio(); } void MainComponent::prepareToPlay(int block,double rate){engine.prepare(rate,block); engine.strike(.8f,.65f);} void MainComponent::getNextAudioBlock(const AudioSourceChannelInfo& info){engine.render(*info.buffer,info.startSample,info.numSamples);} void MainComponent::releaseResources(){} void MainComponent::resized(){editor.setBounds(getLocalBounds());} void MainComponent::handleIncomingMidiMessage(juce::MidiInput*,const juce::MidiMessage& m){if(m.isNoteOn())engine.strike(m.getFloatVelocity(),engine.parameters.position.load());} }
